// Idle original-control glyphs from the f1786ebe Sound matrix. The four
// dependent shapes read only values from the same owner and original bank.
const chicago=[1,2,3,4,5,6,11,12,13,14,15,16,17];
const miami=[1,2,3,4,5,7,8,9,10,12,13,14,15];
const dependencies=[{3:[2],4:[2,3],14:[13],15:[13],16:[13]},{12:[11],13:[11,12]}];
const round=Math.round, trunc=Math.trunc, f32=Math.fround;
const pot=raw=>f32(raw/127);
const clamp=q=>Math.max(0,Math.min(1,q));
const rawPot=v=>Number.isInteger(v)&&v>=0&&v<=127;
const selector=(v,n)=>round(v*(n-1)/127);
export function originalSoundGlyphRole(row){
 if(row?.kind!==1||row.target!==2||![0,1].includes(row.voice))return null;
 if(row.sourceBank===0&&chicago.includes(row.parameter))return 'SOURCE CHICAGO '+row.parameter;
 if(row.sourceBank===1&&miami.includes(row.parameter))return 'SOURCE MIAMI '+row.parameter;
 return null;
}
export function originalSoundGlyphDependencies(row){
 return originalSoundGlyphRole(row)?dependencies[row.sourceBank][row.parameter]??[]:[];
}

const centered=raw=>raw<64?raw/128:.5+(raw-64)/126;
const wobbleRates=['1/2','1/4','1/8','1/16','1/3','1/6','1/12','1/24'];
const signed=(value,digits=0)=>(value>0?'+':'')+value.toFixed(digits);
export function miamiDraftDisplay(parameter,raw){
 if(!rawPot(raw))return null;
 if(parameter===3){
  const carrier=f32(round(f32((.25+.5*pot(raw))*1200))/1200);
  return signed(round(carrier*48)-24)+' st';
 }
 if(parameter===7){
  const amount=round(f32((.25+.5*centered(raw))*2000))-1000;
  return signed(amount/10,1)+' %';
 }
 if(parameter===13)return wobbleRates[selector(raw,8)];
 return null;
}

function lowpass(cutoff,peak){
 const pivot=4+round(f32(pot(cutoff)*14));
 return [
  ['R',0,18,26,1,true],['L',0,5,pivot-3,5,false],
  ['L',pivot-3,5,pivot,5-round(f32(pot(peak)*5)),false],
  ['L',pivot,5-round(f32(pot(peak)*5)),pivot+6,18,false],
  ['L',pivot+6,18,25,18,false]
 ];
}
function filterEnvelope(raw,cutoff,peak){
 const knee=value=>2+round(f32(clamp(f32(f32(value+.5)*.5))*19));
 const cut=pot(cutoff),depth=f32(f32(2*pot(raw))-1);
 const at=knee(cut),target=knee(f32(cut+depth)),top=5-round(f32(pot(peak)*5));
 const strokes=[['R',0,18,26,1,true]];
 if(target!==at)strokes.push(['R',target,15,1,3,true]);
 if(at-2>0)strokes.push(['L',0,6,at-2,6,false]);
 strokes.push(['L',at-2,6,at,top,false],['L',at,top,at+4,18,false]);
 if(at+4<25)strokes.push(['L',at+4,18,25,18,false]);
 return strokes;
}
function wobble(shapeRaw,depth){
 const q=f32(depth*f32(6/127)),shape=selector(shapeRaw,4),strokes=[['R',0,18,26,1,true]];
 if(!q)return [...strokes,['R',0,9,26,1,false]];
 let previous=9;
 for(let i=0;i<26;i++){
  const t=f32(-1+f32(2*i/25));
  const wave=[f32(1-2*Math.abs(t)),-t,t,t>=0?-1:1][shape];
  const y=9-trunc(f32(f32(q*wave)+(wave<0?-.5:.5)));
  if(i)strokes.push(['L',i-1,previous,i,y,false]);
  previous=y;
 }
 return strokes;
}
const op=['L','R','C'];
function decode(frame){
 const bytes=atob(frame),strokes=[];
 for(let i=0;i<bytes.length;i+=5){
  const kind=bytes.charCodeAt(i);
  strokes.push([op[kind%3],bytes.charCodeAt(i+1)-2,bytes.charCodeAt(i+2)-2,bytes.charCodeAt(i+3)-2,bytes.charCodeAt(i+4)-2,kind>=3]);
 }
 return strokes;
}
function staticGlyph(bank,parameter,raw){
 const intervals=table[bank+':'+parameter];
 if(!intervals)return [];
 let i=intervals.length-2;
 while(intervals[i]>raw)i-=2;
 return decode(frames[intervals[i+1]]);
}
export function originalSoundGlyphPrimitives(role,raw,pots=[]){
 const id=/^SOURCE (CHICAGO|MIAMI) (\d+)$/.exec(role??'');
 if(!id||!rawPot(raw))return null;
 const bank=id[1]==='CHICAGO'?0:1,parameter=Number(id[2]);
 if(!(bank===0?chicago:miami).includes(parameter)||(bank===0&&parameter===17&&raw>11))return null;
 const inputs=dependencies[bank][parameter]??[];
 if(pots.length!==inputs.length||pots.some(value=>!rawPot(value)))return {primitives:[],muted:false};
 let primitives;
 if(bank===0&&parameter===3)primitives=lowpass(pots[0],raw);
 else if(bank===0&&parameter===4)primitives=filterEnvelope(raw,...pots);
 else if(bank===1&&parameter===12)primitives=wobble(pots[0],raw);
 else if(bank===1&&parameter===13)primitives=wobble(...pots);
 else primitives=staticGlyph(bank,parameter,raw);
 const muted=bank===0&&([14,15,16].includes(parameter)?pots[0]<64:parameter===4&&2*pot(raw)-1<0);
 return {primitives,muted};
}

// Preserve the native 26x19 cell in the existing R22 glyph viewport.
const scaleX=38/26,scaleY=22/19;
const x=v=>1+v*scaleX,y=v=>1+v*scaleY;
const stroke=points=>points.map(([a,b],i)=>(i?'L':'M')+x(a).toFixed(2)+' '+y(b).toFixed(2)).join('');
export function originalSoundGlyphPaths(role,raw,pots){
 const shape=originalSoundGlyphPrimitives(role,raw,pots);
 if(!shape)return null;
 let d='',guide='';
 const rects=[];
 for(const [kind,gx,gy,a,b,dim] of shape.primitives){
  if(kind==='R')rects.push({x:x(gx),y:y(gy),w:a*scaleX,h:b*scaleY,ink:dim?'guide':'primary',radius:0});
  else{
   const path=kind==='L'?stroke([[gx,gy],[a,b]]):stroke(Array.from({length:17},(_,i)=>[
    gx+Math.cos(i*Math.PI/8)*(a-.5),gy+Math.sin(i*Math.PI/8)*(a-.5)
   ]));
   if(dim)guide+=path;else d+=path;
  }
 }
 return {d,guide,rects,muted:shape.muted};
}

